using System;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.UI;
using Newtonsoft.Json.Linq;
namespace LastRail.Presentation.Battle {
 // Borrows logical clock and authoritative event input. Owns only local presentation and its callbacks/FX children.
 [ExecuteAlways] public sealed class KyleApprovedActorView : MonoBehaviour {
  [SerializeField] Image actor,projectile,impact;[SerializeField] KyleMuzzleFlashGraphic flash;
  [SerializeField] Sprite[] idleFrames,attackFrames,impactFrames;[SerializeField] int[] idleMs,attackMs;
  [SerializeField] KyleFacing facing;[SerializeField] Vector2 muzzle;[SerializeField] float rotation;
  KylePresentationTimeline timeline;Action<string,long> fire;bool bound,missed;long hitAt;Vector2 hitPoint;string hitId;readonly Dictionary<string,(long at,Vector2 point,string cue)> hitReceipts=new Dictionary<string,(long,Vector2,string)>();readonly HashSet<string> terminalMisses=new HashSet<string>();
  public KylePresentationTimeline Timeline=>timeline;public bool Bound=>bound;public Image ActorImage=>actor;public Image ProjectileImage=>projectile;public Image ImpactImage=>impact;public KyleMuzzleFlashGraphic Flash=>flash;
  public void Configure(Image actorImage,Sprite[] idle,Sprite[] attack,int[] idleDurations,int[] attackDurations,Sprite bullet,Sprite[] hit,KyleFacing direction,Vector2 muzzleLocal,float rotationYUp){if(bound||actorImage==null||idle==null||idle.Length!=12||attack==null||attack.Length!=12||bullet==null||hit==null||hit.Length!=8)throw new ArgumentException("Approved Kyle presentation input missing");actor=actorImage;idleFrames=(Sprite[])idle.Clone();attackFrames=(Sprite[])attack.Clone();impactFrames=(Sprite[])hit.Clone();idleMs=(int[])idleDurations.Clone();attackMs=(int[])attackDurations.Clone();timeline=new KylePresentationTimeline(idleMs,attackMs);facing=direction;muzzle=muzzleLocal;rotation=rotationYUp;projectile=Child<Image>("IndependentProjectile");projectile.sprite=bullet;projectile.rectTransform.sizeDelta=new Vector2(22,12);impact=Child<Image>("IndependentAuthoritativeImpact");impact.rectTransform.sizeDelta=new Vector2(192,192);flash=Child<KyleMuzzleFlashGraphic>("IndependentCanvasMuzzleFlash");flash.rectTransform.sizeDelta=new Vector2(26,26);HideFx();}
  T Child<T>(string name)where T:Graphic{var go=new GameObject(name,typeof(RectTransform),typeof(CanvasRenderer),typeof(T));go.transform.SetParent(actor.transform,false);var rect=go.GetComponent<RectTransform>();rect.anchorMin=rect.anchorMax=actor.rectTransform.pivot;rect.pivot=new Vector2(.5f,.5f);var graphic=go.GetComponent<T>();graphic.raycastTarget=false;return graphic;}
  public void Bind(Action<string,long> expressionFire){if(actor==null||projectile==null||impact==null||flash==null)throw new InvalidOperationException("Configure approved assets first");if(timeline==null)timeline=new KylePresentationTimeline(idleMs,attackMs);fire=expressionFire;bound=true;var animator=GetComponent<Animator>();if(animator!=null)animator.enabled=false;}
  public void Unbind(){bound=false;fire=null;timeline?.EndBinding();hitId=null;HideFx();}
  void OnDisable()=>Unbind();void OnDestroy()=>Unbind();
  public void Present(CombatUnitAnimationState state,KyleFacing direction,long originalStartMs,long logicalMs){if(!bound)return;if(direction!=facing)throw new ArgumentException("Use explicit approved directional view");if(logicalMs<timeline.LastMs||logicalMs<originalStartMs)throw new ArgumentException("Original logical time required before publishing cue");bool began=timeline.Begin(state,direction,originalStartMs);if(began)missed=false;Render(logicalMs);}
  public void Render(long logicalMs){if(!bound)return;bool fired=timeline.Sample(logicalMs,out int frame,out bool attacking);actor.sprite=(attacking?attackFrames:idleFrames)[frame];long age=timeline.FireAge(logicalMs);bool flying=!missed&&age>=0&&age<300;projectile.enabled=flying;flash.enabled=!missed&&age>=0&&age<90;float radians=rotation*Mathf.Deg2Rad;var direction=new Vector2(Mathf.Cos(radians),Mathf.Sin(radians));if(flying){projectile.rectTransform.anchoredPosition=muzzle+direction*(11+age*.001f*420);projectile.rectTransform.localRotation=Quaternion.Euler(0,0,rotation);}if(flash.enabled){flash.rectTransform.anchoredPosition=muzzle;flash.rectTransform.localRotation=Quaternion.Euler(0,0,rotation);flash.color=new Color(1,1,1,1-age/90f);}long hitAge=logicalMs-hitAt;impact.enabled=hitId!=null&&hitAge>=0&&hitAge<160;if(impact.enabled){impact.sprite=impactFrames[(int)(hitAge/20)];impact.rectTransform.anchoredPosition=hitPoint;}if(fired&&!missed)fire?.Invoke(timeline.CueId,checked(originalFireAt(logicalMs,age)));}
  static long originalFireAt(long now,long age)=>now-age;
  // This is display input only. Caller must supply the original HIT and location from its authoritative owner.
  public bool AuthoritativeHit(string eventId,string sourceCueId,Vector2 point,long originalLogicalMs){if(!bound)return false;if(string.IsNullOrWhiteSpace(eventId)||string.IsNullOrWhiteSpace(sourceCueId)||float.IsNaN(point.x)||float.IsNaN(point.y)||float.IsInfinity(point.x)||float.IsInfinity(point.y)||originalLogicalMs<0)throw new ArgumentException("Original HIT required");if(!timeline.CanConsumeEvent(sourceCueId)||terminalMisses.Contains(sourceCueId))return false;if(hitReceipts.TryGetValue(eventId,out var old)){if(old.at!=originalLogicalMs||old.point!=point||old.cue!=sourceCueId)throw new ArgumentException("HIT identity conflict");return false;}if(hitReceipts.Count>=KylePresentationTimeline.Capacity)throw new InvalidOperationException("Bounded HIT presentation capacity");hitReceipts.Add(eventId,(originalLogicalMs,point,sourceCueId));hitId=eventId;hitAt=originalLogicalMs;hitPoint=point;if(sourceCueId==timeline.CueId){missed=true;projectile.enabled=false;flash.enabled=false;}return true;}
  public void AuthoritativeMiss(string cueId){if(!bound||!timeline.CanConsumeEvent(cueId))return;if(terminalMisses.Count>=KylePresentationTimeline.Capacity&&!terminalMisses.Contains(cueId))throw new InvalidOperationException("Bounded MISS capacity");terminalMisses.Add(cueId);if(cueId==timeline.CueId){missed=true;projectile.enabled=false;flash.enabled=false;}}
  public void Cancel(){timeline?.Cancel();hitId=null;HideFx();}
  public JObject CaptureTimeline()=>timeline.Capture();public void RestoreTimeline(JObject snapshot){if(timeline==null)timeline=new KylePresentationTimeline(idleMs,attackMs);timeline.Restore(snapshot);hitId=null;HideFx();}
  void HideFx(){if(projectile!=null)projectile.enabled=false;if(impact!=null)impact.enabled=false;if(flash!=null)flash.enabled=false;}
 }
}